# -*- coding: utf-8 -*-
from core import *
import math

R, C = M['R'], M['C']
PROJ = [BASE['n_res'][y] + BASE['n_com'][y] for y in range(5)]

# ---------------- market sizing (single source of truth) ----------------
MK = dict(new=44000, unfinished=.70, pro=.30, reno=.25, comm=.25, g_d=.06, g_s=.04,
          tierA=(40, 22), tierB=(380, 24), fee_res=190 * 420, fee_com=300 * 560)
MK['res_new'] = MK['new'] * MK['unfinished'] * MK['pro']
MK['res_reno'] = MK['res_new'] * MK['reno']
MK['res'] = MK['res_new'] + MK['res_reno']
MK['com'] = MK['res'] * MK['comm']
MK['demand'] = MK['res'] + MK['com']
MK['supply'] = MK['tierA'][0] * MK['tierA'][1] + MK['tierB'][0] * MK['tierB'][1]
MK['gap'] = MK['demand'] - MK['supply']
MK['pool'] = MK['res'] * MK['fee_res'] + MK['com'] * MK['fee_com']
DEM = [MK['demand'] * (1 + MK['g_d']) ** i for i in range(6)]
SUP = [MK['supply'] * (1 + MK['g_s']) ** i for i in range(6)]
GAP = [d - s for d, s in zip(DEM, SUP)]
MYRS = ["2026", "2027", "2028", "2029", "2030", "2031"]
SHARE = [PROJ[y] / DEM[y + 1] for y in range(5)]
GAPSHARE = [PROJ[y] / GAP[y + 1] for y in range(5)]


def cover():
    art = '<svg class="art" viewBox="0 0 210 297" preserveAspectRatio="xMidYMid slice" xmlns="http://www.w3.org/2000/svg">'
    for i in range(9):
        r = 30 + i * 13
        art += f'<path d="M{20 - r * .0:.0f},297 L{20},{250 - r * 1.1:.0f} A{r},{r} 0 0 1 {20 + 2 * r},{250 - r * 1.1:.0f} L{20 + 2 * r},297" fill="none" stroke="#C97A1E" stroke-opacity="{.5 - i * .045:.2f}" stroke-width=".35"/>'
    for i in range(14):
        art += f'<line x1="0" x2="210" y1="{150 + i * 11}" y2="{150 + i * 11}" stroke="#fff" stroke-opacity=".035" stroke-width=".3"/>'
        art += f'<line y1="140" y2="297" x1="{i * 16}" x2="{i * 16}" stroke="#fff" stroke-opacity=".035" stroke-width=".3"/>'
    art += '<rect x="0" y="0" width="7" height="297" fill="#C97A1E"/></svg>'
    from part_c import photo_uri
    u = photo_uri("cover")
    ph = f'<div class="cph" style="background-image:url({u})"></div>' if u else ""
    return f'''<div class="cover">{ph}{art if not u else '<svg class="art" viewBox="0 0 210 297" xmlns="http://www.w3.org/2000/svg"><rect x="0" y="0" width="7" height="297" fill="#C97A1E"/></svg>'}<div class="inner" style="top:{'128mm' if u else '34mm'}">
<div class="tag">دراسة جدوى اقتصادية تفصيلية  |  مقدمة إلى الجهات التمويلية والمستثمرين</div>
<h1>مكتب تصميم داخلي متكامل الخدمات<br>في القاهرة الجديدة</h1>
<div class="rule"></div>
<div class="sub">دراسة السوق والدراسات التسويقية والتنظيمية والتشغيلية والفنية والمالية، مع التحليل الاستراتيجي وتقييم جاذبية الفرصة الاستثمارية</div>
</div>
<div class="meta"><div><b>جمهورية مصر العربية</b>محافظة القاهرة، التجمع الخامس</div><div><b>أفق الدراسة</b>خمس سنوات تشغيلية (2027 إلى 2031)</div><div><b>تاريخ الإصدار</b>نوفمبر 2026، الإصدار الأول</div></div></div>'''


def front():
    return f'''<div class="front"><h1>بيان مهم وحدود الدراسة</h1>
<p>أُعدت هذه الدراسة لغرض تقييم الجدوى الاقتصادية لتأسيس مكتب تصميم داخلي متكامل الخدمات في القاهرة الجديدة، وتقديمها إلى الجهات التمويلية والمستثمرين المحتملين لدعم قرار التمويل. تعتمد الدراسة على بيانات ثانوية منشورة حتى منتصف نوفمبر 2026، وعلى افتراضات تشغيلية ومالية مبنية على ممارسات السوق المصرية في نشاط التصميم الداخلي وإدارة التشطيبات.</p>
<p>الأرقام الواردة في هذه الدراسة نوعان. النوع الأول بيانات منشورة من جهات رسمية أو مؤسسات بحثية، وقد أُشير إلى مصدرها أسفل كل شكل أو جدول. النوع الثاني تقديرات أعدها فريق الدراسة حيث لا تتوافر إحصاءات رسمية، وأبرزها عدد مكاتب التصميم المنظمة وطاقتها ونسبة الملاك الذين يستعينون بمكتب متخصص، وقد وُسمت هذه التقديرات صراحة بعبارة "تقدير فريق الدراسة". نوصي بالتحقق من هذه التقديرات عبر مسح ميداني قبل الإغلاق المالي.</p>
<p>التوقعات المالية ليست ضماناً للنتائج الفعلية. تتأثر النتائج بسعر الصرف وأسعار الفائدة ووتيرة تسليم الوحدات العقارية وقدرة الإدارة على استقطاب العملاء، وقد عولجت هذه العوامل في تحليل الحساسية وتحليل السيناريوهات والمحاكاة الاحتمالية في القسم المالي. جميع المبالغ بالجنيه المصري ما لم يُذكر غير ذلك، وأسعار الخدمات لا تشمل ضريبة القيمة المضافة.</p>
<h2>هيكل الدراسة</h2>
<p>رُتبت الدراسة وفق التسلسل الذي تتبعه لجان الائتمان والاستثمار عند المراجعة: الارتباط الاستراتيجي والحاجة السوقية أولاً، ثم العرض والطلب والفجوة، ثم قدرة المشروع على التنفيذ تسويقياً وتنظيمياً وتشغيلياً وفنياً، ثم الأثر المالي والمخاطر، وتنتهي بالقرار الاستثماري وأدلته.</p>
</div>'''


def toc_page(pages):
    rows = "".join(f'<tr><td class="n">{n:02d}</td><td><a href="#{sid}">{t}</a></td><td class="pg">{pages.get(sid, "")}</td></tr>' for sid, n, t in TOC)
    return f'<div class="front"><h1>المحتويات</h1><table class="toc">{rows}</table></div>'


def s_exec():
    o = sec(1, "الملخص التنفيذي", "تقيّم هذه الدراسة تأسيس مكتب تصميم داخلي متكامل الخدمات في التجمع الخامس بالقاهرة الجديدة، يخدم ملاك الوحدات السكنية في المجمعات العمرانية بشرق وغرب القاهرة والساحل الشمالي، إضافة إلى المساحات الإدارية والتجارية والطبية. يقدم المكتب التصميم واللوحات التنفيذية والإشراف وإدارة التنفيذ بنظام التكلفة مضافاً إليها أتعاب، وتوريد الأثاث.")
    o += kpis([
        (mn(M['invest'], 2), "إجمالي الاستثمار (مليون جنيه)", f"منها {mn(M['wc_reserve'], 2)} مليون احتياطي سيولة"),
        (pct(M['irr_tv']), "معدل العائد الداخلي للمشروع", f"مقابل تكلفة رأس مال {pct(M['wacc'], 0)}"),
        (mn(M['npv_tv'], 1), "صافي القيمة الحالية (مليون جنيه)", "شاملة القيمة الاستمرارية"),
        (f"{M['payback']:.1f}", "فترة الاسترداد (سنة)", f"المخصومة {M['dpayback_tv']:.1f} سنة"),
    ])
    o += h2("الفرصة السوقية")
    o += p(f"يستند الطلب إلى واقع ثابت في السوق العقارية المصرية: الغالبية العظمى من وحدات المطورين تُسلَّم نصف تشطيب، فيتحمل المالك التصميم والتشطيب كاملين. سجّلت أكبر عشر شركات تطوير مبيعات تعاقدية بنحو 670 مليار جنيه في النصف الأول من 2026 لنحو 39 ألف وحدة، وتركز 47% منها في شرق القاهرة و33% في الساحل الشمالي. نقدّر الطلب السنوي على خدمات التصميم الداخلي المتخصصة في النطاق المستهدف بنحو {num(MK['demand'])} مشروع، مقابل طاقة للمكاتب المنظمة تقارب {num(MK['supply'])} مشروع، أي فجوة نحو {num(MK['gap'])} مشروع سنوياً ({pct(MK['gap'] / MK['demand'], 0)} من الطلب) يغطيها حالياً مصممون أفراد ومقاولون دون منهجية تصميم أو إشراف موثق.")
    o += h2("نموذج العمل والنتائج المالية")
    o += p(f"يبدأ المكتب بفريق من {M['head'][0]:.0f} أفراد في مقر مساحته 120 متراً مربعاً، وينفذ {PROJ[0]} مشروعاً في السنة الأولى ترتفع إلى {PROJ[4]} مشروعاً في السنة الخامسة، وهو ما يمثل {pct(SHARE[4], 2)} فقط من الطلب المقدّر في النطاق المستهدف. تنمو الإيرادات من {mn(R['total'][0], 1)} مليون جنيه إلى {mn(R['total'][4], 1)} مليون جنيه، ويتحول هامش الأرباح قبل الفوائد والضرائب والإهلاك من {pct(M['ebitda'][0] / R['total'][0])} في السنة الأولى إلى {pct(M['ebitda'][4] / R['total'][4])} في السنة الخامسة.")
    rows = [
        ["الإيرادات"] + [mn(v) for v in R['total']],
        ["المصروفات التشغيلية"] + [mn(v) for v in C['total']],
        ["الأرباح قبل الفوائد والضرائب والإهلاك"] + [mn(v) for v in M['ebitda']],
        ["صافي الربح"] + [mn(v) for v in M['ni']],
        ["الرصيد النقدي آخر السنة"] + [mn(v) for v in M['cash']],
        ["عدد المشروعات"] + [str(v) for v in PROJ],
    ]
    o += table(["البند (مليون جنيه)"] + YRS, rows, "ملخص النتائج المالية المتوقعة في الحالة الأساسية", cls="numt", widths=[35, 13, 13, 13, 13, 13])
    o += fig(bars(YRS, [("الإيرادات", [v / 1e6 for v in R['total']]), ("الأرباح قبل الفوائد والضرائب والإهلاك", [v / 1e6 for v in M['ebitda']])], unit="مليون جنيه", h=250, legend_gap=90), "تطور الإيرادات والأرباح التشغيلية خلال سنوات الدراسة")
    o += h2("خلاصة التقييم")
    o += p(f"الفرصة جذابة بشروط. المؤشرات المالية في الحالة الأساسية تتجاوز الحد الأدنى المطلوب: معدل العائد الداخلي على التدفقات الخمسية دون قيمة استمرارية يبلغ {pct(M['irr'])} مقابل تكلفة رأس مال {pct(M['wacc'], 0)}، ويرتفع إلى {pct(M['irr_tv'])} عند احتساب القيمة الاستمرارية. المحاكاة الاحتمالية بعشرة آلاف تجربة تُظهر أن صافي القيمة الحالية موجب في {pct(MCS['p_tv'], 0)} من الحالات. في المقابل، المشروع حساس لحجم المشروعات المتعاقد عليها ولنسبة العملاء الذين يسندون التنفيذ للمكتب، والسنة الأولى خاسرة تشغيلياً. لذلك نوصي بالتمويل مع ثلاثة شروط مفصلة في القسم الأخير: احتياطي سيولة لا يقل عن ستة أشهر، وربط التعيينات بالعقود الموقعة، وتسهيل ائتماني احتياطي غير مسحوب.")
    return o + end()


def s_method():
    o = sec(2, "المنهجية ومصادر البيانات", "اتبعت الدراسة منهجية الدراسات الخمس المعتمدة في مراجعة المشروعات الرأسمالية: الاستراتيجية والاقتصادية والتجارية والمالية والإدارية، وأضافت إليها الدراستين الفنية والتشغيلية بما يناسب مشروعاً خدمياً خاصاً.")
    o += h2("مراحل إعداد الدراسة")
    steps = [("تحديد النطاق", "تعريف الخدمة والشريحة والنطاق الجغرافي"), ("البحث المكتبي", "بيانات رسمية وتقارير قطاعية ومنصات عقارية"), ("تقدير السوق", "من أعلى لأسفل ومن أسفل لأعلى ثم المطابقة"), ("تصميم النموذج", "هيكل الخدمات والتسعير والطاقة والتنظيم"), ("النمذجة المالية", "قوائم تقديرية وتدفقات مخصومة"), ("اختبار المخاطر", "حساسية وسيناريوهات ومحاكاة مونت كارلو"), ("القرار", "بطاقة تقييم مرجحة وتوصيات")]
