    b += T(330, 16, "سعر مرتفع", "m", 8.5, MUTE) + T(330, 292, "سعر منخفض", "m", 8.5, MUTE) + T(545, 166, "خدمة متكاملة وشفافة", "m", 8.5, MUTE) + T(115, 166, "تصميم فقط أو تنفيذ فقط", "m", 8.5, MUTE)
    for x, y, r, col, lab in [(470, 62, 26, S1, "المكاتب الرائدة"), (410, 150, 34, S3, "المكاتب المتوسطة"), (150, 232, 30, S4, "المصممون الأفراد"), (250, 205, 30, MUTE, "المقاولون")]:
        b += f'<circle cx="{x}" cy="{y}" r="{r}" fill="{col}" fill-opacity=".22" stroke="{col}" stroke-width="1.5"/>' + T(x, y + 3, lab, "m", 8.5, INK, 600)
    b += f'<circle cx="525" cy="118" r="20" fill="{COPPER}" stroke="#fff" stroke-width="2"/>' + T(525, 121, "المشروع", "m", 8.5, "#fff", 700)
    o += fig(svg(W, H, b), "خريطة التموضع التنافسي: السعر مقابل تكامل الخدمة وشفافيتها", "تحليل فريق الدراسة", "حجم الدائرة يعبر تقريبياً عن حجم المجموعة في السوق.")
    o += h2("تحليل القوى الخمس لبورتر")
    o += grid([
        card('تهديد الداخلين الجدد <span class="pill r">مرتفع</span>', "حواجز الدخول منخفضة: رأس مال محدود وبرمجيات متاحة. الحاجز الفعلي هو معرض الأعمال والسمعة."),
        card('قوة العملاء التفاوضية <span class="pill a">متوسطة إلى مرتفعة</span>', "العميل يقارن ثلاثة عروض على الأقل، وتكلفة التحول قبل التعاقد صفر، لكنها ترتفع كثيراً بعد اعتماد التصميم."),
        card('قوة الموردين <span class="pill a">متوسطة</span>', "الكفاءات التصميمية المتميزة نادرة وتتنقل، وموردو البرمجيات يسعّرون بالدولار. موردو الخامات كثيرون."),
        card('تهديد البدائل <span class="pill a">متوسط</span>', "تطبيقات التصميم بالذكاء الاصطناعي والتشطيب المباشر عبر مقاول. تصلح للأفكار الأولية ولا تنتج لوحات تنفيذية معتمدة."),
        card('شدة التنافس <span class="pill r">مرتفعة</span>', "عدد كبير من اللاعبين وتمايز بصري صعب الحماية. التنافس على الانتباه الرقمي يرفع تكلفة اكتساب العميل."),
        card("الخلاصة", "جاذبية هيكلية متوسطة. الربحية تأتي من الانضباط التشغيلي ومن التموضع في منطقة لا يخدمها المنافسون جيداً، لا من هيكل السوق نفسه.", "nv"),
    ], 3)
    o += h2("الميزة التفاضلية المقترحة")
    o += p("فصل أتعاب المكتب عن قيمة المقاولة. يتقاضى المكتب أتعاب تصميم ثابتة للمتر، ثم أتعاب إدارة تنفيذ بنسبة معلنة من التكلفة الفعلية، ويطّلع العميل على عروض المقاولين والموردين وفواتيرهم. هذا النموذج يعالج الشكوى الأكثر تكراراً من عملاء المكاتب المتوسطة وشركات التشطيب، وهي غموض هوامش التنفيذ، وهو أيضاً يحمي المكتب من مخاطر رأس المال العامل لأن مستحقات المقاولين تمر عبر العميل.")
    return o + end()


